mesSim(document.getElementById("sim-l22"),Object.assign({id:"l22"},{kind:"term",title:"PowerShell: kiểm tra công cụ và tạo kho Git",sub:"Gõ lệnh rồi Enter (↑ để gọi lại lệnh cũ). Kết quả là ví dụ, máy bạn có thể khác số phiên bản.",
 cwd:"C:\\Users\\hocvien",vars:{git:false,files:[],staged:[],commits:[],tags:[],name:null},
 hints:["python --version","git --version","mkdir C:\\amts\\mini-mes","cd C:\\amts\\mini-mes","git init","git config user.name \"Hoc Vien\"","echo \"# AMTS Mini-MES\" > README.md","git add README.md","git commit -m \"Đặc tả v0.1\"","git tag v0.1-dac-ta","git log --oneline --decorate"],
 cmds:[{re:/^python --version$/i,out:"Python 3.13.0"},{re:/^git --version$/i,out:"git version 2.47.0.windows.1"},{re:/^code --version$/i,out:"1.95.0"},
  {re:/^mkdir\s+(.+)$/i,out:m=>"    Directory: "+m[1].replace(/\\[^\\]+$/,"")+"\n\nMode   Name\n----   ----\nd----  "+m[1].split("\\").pop()},
  {re:/^cd\s+(.+)$/i,out:"",fx:(m,S)=>{S.cwd=m[1].replace(/^\.\\/,S.cwd+"\\")}},
  {re:/^git init$/i,out:(m,S)=>"Initialized empty Git repository in "+S.cwd+"\\.git\\",fx:(m,S)=>{S.git=true}},
  {re:/^git config user\.(name|email)\s+"?([^"]+)"?$/i,out:"",fx:(m,S)=>{if(m[1]==="name")S.name=m[2]}},
  {re:/^echo\s+"?([^">]*)"?\s*>\s*(\S+)$/i,out:"",fx:(m,S)=>{if(!S.files.includes(m[2]))S.files.push(m[2])}},
  {re:/^git add\s+(\S+)$/i,out:(m,S)=>!S.git?{err:"fatal: not a git repository (or any of the parent directories): .git"}:(m[1]==="."||S.files.includes(m[1]))?"":{err:"fatal: pathspec '"+m[1]+"' did not match any files"},fx:(m,S)=>{if(S.git)S.staged=m[1]==="."?S.files.slice():S.staged.concat(m[1])}},
  {re:/^git commit -m\s+"([^"]+)"$/i,out:(m,S)=>!S.git?{err:"fatal: not a git repository"}:!S.staged.length?{err:"nothing to commit (create/copy files and use \"git add\" to track)"}:!S.name?{err:"Author identity unknown\n\n*** Please tell me who you are.\n\n  git config user.name \"Your Name\""}:"[main (root-commit) 3f2a9c1] "+m[1]+"\n "+S.staged.length+" file changed",
   fx:(m,S)=>{if(S.git&&S.staged.length&&S.name){S.commits.push(m[1]);S.staged=[]}}},
  {re:/^git tag\s+(\S+)$/i,out:(m,S)=>S.commits.length?"":{err:"fatal: Failed to resolve 'HEAD' as a valid ref."},fx:(m,S)=>{if(S.commits.length)S.tags.push(m[1])}},
  {re:/^git log( --oneline)?( --decorate)?$/i,out:(m,S)=>S.commits.length?S.commits.map((c,i)=>"3f2a9c"+(i+1)+(i===S.commits.length-1?" (HEAD -> main"+(S.tags.length?", tag: "+S.tags.join(", tag: "):"")+")":"")+" "+c).reverse().join("\n"):{err:"fatal: your current branch 'main' does not have any commits yet"}},
  {re:/^git status$/i,out:(m,S)=>!S.git?{err:"fatal: not a git repository"}:S.staged.length?"Changes to be committed:\n\tnew file:   "+S.staged.join("\n\tnew file:   "):S.files.length&&!S.commits.length?"Untracked files:\n\t"+S.files.join("\n\t"):"nothing to commit, working tree clean"}],
 tasks:[{t:"Kiểm tra Python và Git đã cài, có trong PATH.",ok:"Nếu báo “not recognized”, mở cửa sổ PowerShell mới hoặc cài lại và đánh dấu Add python.exe to PATH.",check:s=>s.ran(/^python --version$/i)&&s.ran(/^git --version$/i)},
  {t:"Tạo thư mục C:\\amts\\mini-mes, vào thư mục đó, chạy <code>git init</code>.",check:s=>s.S.git&&/mini-mes/.test(s.S.cwd)},
  {t:"Tạo README.md, đặt tên người dùng Git, add và commit.",hint:"Thứ tự: git config user.name …; echo … > README.md; git add README.md; git commit -m \"…\"",check:s=>s.S.commits.length>0},
  {t:"Gắn thẻ <code>v0.1-dac-ta</code> cho commit và xem bằng <code>git log --oneline --decorate</code>.",ok:"Mỗi mốc dự án là một commit có thẻ: quay lại đúng trạng thái khi cần.",check:s=>s.S.tags.includes("v0.1-dac-ta")&&s.ran(/^git log/i)}]}));

